function C:CommentSelect_Prev()
  if not coroutine.isyieldable() then spawn(C.CommentSelect_Prev, self) return end
  local window = WindowManager.WindowList:Find(function(x) return x.appType == "Broadcast" end)
  if window == nil then
    return
  end
  local component = window.nakamiApp:GetComponent("Live")
  local selectableComments = component.SelectableComments
  local targetComment = nil
  if component.SelectableComments.Count <= 0 then
    return
  end
  if component.SelectingComment == nil then
    targetComment = IDX(selectableComments, selectableComments.Count - 1)
    component:CommentScrollToLatest()
  else
    local num = selectableComments:IndexOf(component.SelectingComment) - 1
    while num >= 0 and num >= 0 do
      if not IDX(selectableComments, num).IsDeleted then
        targetComment = IDX(selectableComments, num)
        component:CommentScrollToTarget(targetComment)
        break
      end
      num = num - 1
    end
  end
  UniTask.Yield()
  if targetComment ~= nil then
    spawn(function() CursorManager:MoveToAsync(targetComment.transform.position, 0.1) end)
  end
end

